1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioResult = {
13	  results: StepResult[];
14	};
15	
16	const BASE_PREMIUMS = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	} as const satisfies Record<string, number>;
24	
25	const INSURANCE_VALUES = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	} as const satisfies Record<keyof typeof BASE_PREMIUMS, number>;
33	
34	type InsurableItemType = keyof typeof BASE_PREMIUMS;
35	
36	type Item = {
37	  type: InsurableItemType;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type QuoteStep = {
44	  op: "quote";
45	  items: Item[];
46	};
47	
48	type Damage = {
49	  itemType: string;
50	  amount: number;
51	};
52	
53	type Incident = {
54	  cause: string;
55	  damages: Damage[];
56	};
57	
58	type ClaimStep = {
59	  op: "claim";
60	  policy: number;
61	  incident: Incident;
62	};
63	
64	type Step = QuoteStep | ClaimStep;
65	
66	type Customer = {
67	  yearsWithMHPCO: number;
68	};
69	
70	type Scenario = {
71	  customer: Customer;
72	  steps: Step[];
73	};
74	
75	const PROCESSING_FEE = 5;
76	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
80	const LOYALTY_THRESHOLD_YEARS = 2;
81	const LOYALTY_DISCOUNT_PERCENT = 20;
82	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
83	
84	const percentOf = (amount: number, percent: number): number =>
85	  (amount * percent) / 100;
86	
87	// The MHPCO always rounds in its own favour: premiums (which the customer
88	// pays) go up. Payouts round down, but no test demands that yet.
89	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
90	
91	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
92	
93	// Exactly this many components of the same type form a "building block",
94	// priced as a unit rather than per item.
95	const BUILDING_BLOCK_SIZE = 3;
96	const BUILDING_BLOCK_BASE_PREMIUM = 60;
97	
98	const sumOf = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
102	
103	const alikeItemGroups = (items: Item[]): Item[][] =>
104	  insurableItemTypes
105	    .map((type) => items.filter((item) => item.type === type))
106	    .filter((alikeItems) => alikeItems.length > 0);
107	
108	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
109	  alikeItems.length === BUILDING_BLOCK_SIZE;
110	
111	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
112	  formsBuildingBlock(alikeItems)
113	    ? BUILDING_BLOCK_BASE_PREMIUM
114	    : sumOf(alikeItems.map(itemBasePremiumOf));
115	
116	const policyBasePremiumOf = (items: Item[]): number =>
117	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
118	
119	const isCursed = (item: Item): boolean => item.cursed === true;
120	
121	const isHighlyEnchanted = (item: Item): boolean =>
122	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
123	
124	// A modifier adjusts a base premium by a percentage of it, when it applies to
125	// the subject it is about (an item, a contract, ...). A surcharge has a
126	// positive percent, a discount a negative one, so they all combine by summing.
127	// Modifiers are cumulative: every applicable one applies.
128	type Modifier<Subject> = {
129	  appliesTo: (subject: Subject) => boolean;
130	  percent: number;
131	};
132	
133	const modifierTotalOf = <Subject>(
134	  modifiers: Modifier<Subject>[],
135	  subject: Subject,
136	  basePremium: number,
137	): number =>
138	  sumOf(
139	    modifiers
140	      .filter((modifier) => modifier.appliesTo(subject))
141	      .map((modifier) => percentOf(basePremium, modifier.percent)),
142	  );
143	
144	const ITEM_MODIFIERS: Modifier<Item>[] = [
145	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
146	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
147	];
148	
149	// Item-specific modifiers apply to the base premium of the affected item.
150	const itemModifierTotalOf = (item: Item): number =>
151	  modifierTotalOf(ITEM_MODIFIERS, item, itemBasePremiumOf(item));
152	
153	const isLongStanding = (customer: Customer): boolean =>
154	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
155	
156	// A contract is one quote within a scenario; contractIndex is zero-based, so
157	// every contract after the first is a follow-up.
158	type Contract = {
159	  customer: Customer;
160	  contractIndex: number;
161	};
162	
163	const isFollowUpContract = (contract: Contract): boolean =>
164	  contract.contractIndex > 0;
165	
166	// Policy-wide modifiers apply to the policy base premium and are about the
167	// contract as a whole rather than any single item.
168	const alwaysApplies = (): boolean => true;
169	
170	const POLICY_MODIFIERS: Modifier<Contract>[] = [
171	  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
172	  {
173	    appliesTo: (contract) => isLongStanding(contract.customer),
174	    percent: -LOYALTY_DISCOUNT_PERCENT,
175	  },
176	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
177	];
178	
179	const policyModifierTotalOf = (
180	  contract: Contract,
181	  policyBasePremium: number,
182	): number => modifierTotalOf(POLICY_MODIFIERS, contract, policyBasePremium);
183	
184	const quote = (step: QuoteStep, contract: Contract): QuoteResult => {
185	  const policyBasePremium = policyBasePremiumOf(step.items);
186	  const itemModifiers = sumOf(step.items.map(itemModifierTotalOf));
187	  const policyModifiers = policyModifierTotalOf(contract, policyBasePremium);
188	
189	  return {
190	    premium: roundedUpInMHPCOsFavour(
191	      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
192	    ),
193	  };
194	};
195	
196	const DEDUCTIBLE_PER_DAMAGE = 100;
197	const CAP_MULTIPLIER = 2;
198	
199	// The MHPCO rounds payouts (which it pays out) down.
200	const roundedDownInMHPCOsFavour = (payout: number): number =>
201	  Math.floor(payout);
202	
203	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];
204	
205	// A policy is created by a quote step and remembers how much of its cap the
206	// customer has already claimed.
207	type Policy = {
208	  items: Item[];
209	  remainingCap: number;
210	};
211	
212	const damagePayoutOf = (damage: Damage): number =>
213	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
214	
215	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
216	  const payout = roundedDownInMHPCOsFavour(
217	    sumOf(step.incident.damages.map(damagePayoutOf)),
218	  );
219	  policy.remainingCap -= payout;
220	
221	  return { payout, remainingCap: policy.remainingCap };
222	};
223	
224	const policyFor = (items: Item[]): Policy => ({
225	  items,
226	  remainingCap: CAP_MULTIPLIER * sumOf(items.map(insuranceValueOf)),
227	});
228	
229	export const runScenario = (scenario: Scenario): ScenarioResult => {
230	  const policies = new Map<number, Policy>();
231	  const results: StepResult[] = [];
232	
233	  scenario.steps.forEach((step, stepIndex) => {
234	    if (step.op === "quote") {
235	      policies.set(stepIndex, policyFor(step.items));
236	      results.push(
237	        quote(step, {
238	          customer: scenario.customer,
239	          contractIndex: policies.size - 1,
240	        }),
241	      );
242	      return;
243	    }
244	
245	    results.push(claim(step, policies.get(step.policy)!));
246	  });
247	
248	  return { results };
249	};
